"""Finalize stage A and the explicit stage B gate, only from retained results."""
import json,subprocess
from workflow import ROOT,LAB,OUT,sha,dump,stamp,game_check,TARGETS
def main():
    native=json.loads(sorted(OUT.glob('NATIVE_REVIEW_*.json'))[-1].read_text(encoding='utf8'));assert native['status']=='PASS'
    integrity=json.loads(sorted(OUT.glob('CHANGED_*.json'))[-1].read_text(encoding='utf8'))
    allowed={'experiments/m1/native_bootstrap/src/bootstrap.cpp','tools/enet-prototype/tests/test_suite.cpp','tools/enet-prototype/tests/test_bridge_acceptance.cpp'}
    assert set(integrity['changed'])==allowed
    baseline=json.loads((OUT/'BASELINE.json').read_text(encoding='utf8'));g=game_check()
    assert not g['errors'] and not g['client_copy_errors'] and g['original_full_snapshot_equal'] and g['protected']==baseline['game']['protected']
    ps="$p=@(Get-CimInstance Win32_Process -Filter \"Name='anubis_Shipping_Steam_x64.exe'\" | Select-Object ProcessId,ExecutablePath);$u=@(Get-NetUDPEndpoint -ErrorAction SilentlyContinue | Where-Object LocalPort -eq 28745 | Select-Object LocalAddress,LocalPort,OwningProcess);@{processes=$p;udp=$u}|ConvertTo-Json -Depth 4"
    r=subprocess.run(['powershell.exe','-NoProfile','-Command',ps],capture_output=True,encoding='utf8',timeout=30);assert r.returncode==0
    os=json.loads(r.stdout);assert not os['processes'] and not os['udp'];dump(OUT/'OS_FINAL.json',os)
    tests=[]
    for name in TARGETS[2:]:
        folder=sorted(OUT.glob('TEST_'+name+'_*'))[-1];o=json.loads((folder/'RESULT.json').read_text(encoding='utf8'));assert o['exit_code']==0
        o['summary']='\n'.join((folder/'console.log').read_text(encoding='utf8').splitlines()[-7:]);tests.append(o)
    configs=[]
    for name in ['N53F_HOST_01','N53F_CLIENT_01']:
        p=LAB/'profile'/name/'early_native_logs/kexengine.cfg'
        source=p.read_text(encoding='utf8');dst=OUT/(name+'_CONFIG_AFTER.cfg');dst.write_text(source,encoding='utf8')
        cleaned='\n'.join(line for line in source.splitlines() if not line.startswith('bind k '))+'\n'
        if source!=cleaned:p.write_text(cleaned,encoding='utf8')
        configs.append(dict(path=str(p),native_after_sha256=sha(dst),cleaned_sha256=sha(p),test_attack_binding_removed=True))
    dump(OUT/'PROFILE_BINDING_CLEANUP.json',configs)
    gate=dict(status='PASS_TO_DOC55',classification='FUNCTIONAL PASS; FULL DOC53 PARTIAL',production_state_or_lifecycle_blockers=[],new_critical_regression_failures=[],tests=tests,native_review=native,integrity=integrity,game=g,os_final=os,
        limitations=['Historical DOC51/52 terminal hang root cause UNKNOWN','K binding was not runtime accepted; default left mouse Attack passed','No native reconnect/loading/cutscene/minimized/world-exit/8-player acceptance','Exact Esc pause predicate not localized; prior bounded Esc result retained','Historical 44/46 timer trigger not uniquely reproduced; delayed-snapshot mechanism reproduced, transient stale view is expected until snapshot'])
